SELECT COUNT(DISTINCT Codigo) AS cantidad_ordenes_agiles
FROM oc_lineas
WHERE EsCompraAgil = 'S';

SELECT COUNT(DISTINCT Codigo) AS cantidad_ordenes_cancelacion_solicitada
FROM oc_lineas
WHERE Estado = 'Cancelación Solicitada';

SELECT COUNT(DISTINCT Codigo) AS cantidad_ordenes_canceladas
FROM oc_lineas
WHERE Estado = 'Cancelación Solicitada';

SELECT 
    (SUM(CASE WHEN EsTratoDirecto = 'Sí' THEN 1 ELSE 0 END) * 100.0 / COUNT(DISTINCT Codigo)) AS PorcentajeTratosDirectos
FROM oc_lineas;

SELECT COUNT(DISTINCT NombreProveedor) AS cantidad_proveedores
FROM oc_lineas
WHERE sector = 'Salud';

SELECT Tipo, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY MontoTotalOC) AS MedianaMonto
FROM oc_lineas
GROUP BY Tipo;

SELECT COUNT(DISTINCT Codigo) AS cantidad_ordenes_licitacion_publica
